def regex_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)
    # dp[i][j] indicates whether s[:i] matches p[:j]
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    # Initialize the first row where s is empty
    for j in range(1, n + 1):
        pc = p[j-1]
        if pc == '*':
            dp[0][j] = dp[0][j-2]
        elif pc == '?':
            dp[0][j] = dp[0][j-2]
        elif pc == '+':
            dp[0][j] = False
        else:
            dp[0][j] = False

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            pc = p[j-1]
            sc = s[i-1]

            if pc == '*':
                ppc = p[j-2]
                match = (sc == ppc or ppc == '.')
                # Zero occurrences: dp[i][j-2]
                # One or more occurrences: match and dp[i-1][j]
                dp[i][j] = dp[i][j-2] or (match and dp[i-1][j])
            elif pc == '+':
                ppc = p[j-2]
                match = (sc == ppc or ppc == '.')
                # One or more occurrences: match and (dp[i-1][j] or dp[i-1][j-2])
                dp[i][j] = match and (dp[i-1][j] or dp[i-1][j-2])
            elif pc == '?':
                ppc = p[j-2]
                match = (sc == ppc or ppc == '.')
                # Zero occurrences: dp[i][j-2]
                # One occurrence: match and dp[i-1][j-1]
                dp[i][j] = dp[i][j-2] or (match and dp[i-1][j-1])
            else:
                if sc == pc or pc == '.':
                    dp[i][j] = dp[i-1][j-1]
                else:
                    dp[i][j] = False

    return dp[m][n]
