def wildcard_match(s: str, p: str) -> bool:
    # Preprocess pattern to collapse consecutive '*' into a single '*'
    processed_p = []
    for ch in p:
        if ch == '*' and processed_p and processed_p[-1] == '*':
            continue
        processed_p.append(ch)
    p = ''.join(processed_p)

    m, n = len(s), len(p)

    # dp[i][j] means s[:i] matches p[:j]
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    # Handle patterns that start with '*'
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 1]
        else:
            break

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                # '*' can match empty (dp[i][j-1]) or one more character (dp[i-1][j])
                dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
            elif p[j - 1] == '?' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = False

    return dp[m][n]
