from datetime import date

def business_days(start: str, end: str, holidays: list[str]) -> int:
    s = date.fromisoformat(start)
    e = date.fromisoformat(end)

    # If start is after end, swap and negate the result
    if s > e:
        return -business_days(end, start, holidays)

    if s == e:
        return 0

    # Convert holiday strings to date objects and store in a set to remove duplicates
    h_dates = {date.fromisoformat(h) for h in holidays}

    # Calculate total days in the range [start, end)
    delta = (e - s).days

    # Calculate full weeks and remaining days
    full_weeks = delta // 7
    rem_days = delta % 7

    # Each full week contributes 5 business days
    count = full_weeks * 5

    # Add business days from the remaining days
    start_weekday = s.weekday()  # Monday is 0, Sunday is 6
    for i in range(rem_days):
        if start_weekday + i < 5:
            count += 1

    # Subtract holidays that fall on weekdays within the range
    for h in h_dates:
        if s <= h < e and h.weekday() < 5:
            count -= 1

    return count
