def parse_json(text: str) -> object:
    class Parser:
        def __init__(self, text):
            self.text = text
            self.pos = 0
            self.length = len(text)

        def peek(self):
            if self.pos < self.length:
                return self.text[self.pos]
            return None

        def advance(self):
            c = self.peek()
            self.pos += 1
            return c

        def skip_ws(self):
            while self.pos < self.length and self.text[self.pos].isspace():
                self.pos += 1

        def parse(self):
            self.skip_ws()
            if self.pos >= self.length:
                raise ValueError("Empty input")
            val = self.parse_value()
            self.skip_ws()
            if self.pos < self.length:
                raise ValueError("Trailing characters")
            return val

        def parse_value(self):
            c = self.peek()
            if c == '{':
                return self.parse_object()
            elif c == '[':
                return self.parse_array()
            elif c == '"':
                return self.parse_string()
            elif c == 't':
                return self.parse_literal('true', True)
            elif c == 'f':
                return self.parse_literal('false', False)
            elif c == 'n':
                return self.parse_literal('null', None)
            elif c == '-' or (c and c.isdigit()):
                return self.parse_number()
            else:
                raise ValueError(f"Unexpected character: {c}")

        def parse_literal(self, expected, value):
            for char in expected:
                if self.advance() != char:
                    raise ValueError(f"Invalid literal: {expected}")
            return value

        def parse_string(self):
            self.advance()  # consume opening "
            chars = []
            while True:
                c = self.advance()
                if c is None:
                    raise ValueError("Unterminated string")
                if c == '"':
                    break
                if c == '\\':
                    esc = self.advance()
                    if esc is None:
                        raise ValueError("Unterminated string escape")
                    if esc == '"':
                        chars.append('"')
                    elif esc == '\\':
                        chars.append('\\')
                    elif esc == '/':
                        chars.append('/')
                    elif esc == 'b':
                        chars.append('\b')
                    elif esc == 'f':
                        chars.append('\f')
                    elif esc == 'n':
                        chars.append('\n')
                    elif esc == 'r':
                        chars.append('\r')
                    elif esc == 't':
                        chars.append('\t')
                    elif esc == 'u':
                        hex_chars = ""
                        for _ in range(4):
                            hc = self.advance()
                            if hc is None or hc not in '0123456789abcdefABCDEF':
                                raise ValueError("Invalid unicode escape")
                            hex_chars += hc
                        try:
                            code_point = int(hex_chars, 16)
                            if code_point > 0x10FFFF:
                                raise ValueError("Invalid unicode code point")
                            chars.append(chr(code_point))
                        except ValueError:
                            raise ValueError("Invalid unicode escape")
                    else:
                        raise ValueError(f"Invalid escape sequence: \\{esc}")
                else:
                    chars.append(c)
            return "".join(chars)

        def parse_number(self):
            start_pos = self.pos
            if self.peek() == '-':
                self.advance()

            if self.pos >= self.length or not self.text[self.pos].isdigit():
                raise ValueError("Invalid number")

            if self.text[self.pos] == '0':
                self.advance()
                if self.pos < self.length and self.text[self.pos].isdigit():
                    raise ValueError("Leading zeros not allowed")
            else:
                while self.pos < self.length and self.text[self.pos].isdigit():
                    self.advance()

            is_float = False
            if self.pos < self.length and self.text[self.pos] == '.':
                is_float = True
                self.advance()
                if self.pos >= self.length or not self.text[self.pos].isdigit():
                    raise ValueError("Invalid number: fractional part missing digits")
                while self.pos < self.length and self.text[self.pos].isdigit():
                    self.advance()

            if self.pos < self.length and self.text[self.pos] in ('e', 'E'):
                is_float = True
                self.advance()
                if self.pos < self.length and self.text[self.pos] in ('+', '-'):
                    self.advance()
                if self.pos >= self.length or not self.text[self.pos].isdigit():
                    raise ValueError("Invalid number: exponent missing digits")
                while self.pos < self.length and self.text[self.pos].isdigit():
                    self.advance()

            num_str = self.text[start_pos:self.pos]
            if is_float:
                return float(num_str)
            else:
                return int(num_str)

        def parse_array(self):
            self.advance()  # consume [
            self.skip_ws()
            if self.peek() == ']':
                self.advance()
                return []

            items = []
            while True:
                items.append(self.parse_value())
                self.skip_ws()
                c = self.peek()
                if c == ']':
                    self.advance()
                    return items
                elif c == ',':
                    self.advance()
                    self.skip_ws()
                    if self.peek() == ']':
                        raise ValueError("Trailing comma in array")
                else:
                    raise ValueError(f"Expected ',' or ']' in array, got {c}")

        def parse_object(self):
            self.advance()  # consume {
            self.skip_ws()
            if self.peek() == '}':
                self.advance()
                return {}

            obj = {}
            while True:
                self.skip_ws()
                if self.peek() != '"':
                    raise ValueError("Object keys must be strings")
                key = self.parse_string()
                self.skip_ws()
                if self.peek() != ':':
                    raise ValueError("Expected ':' in object")
                self.advance()
                self.skip_ws()
                value = self.parse_value()
                obj[key] = value

                self.skip_ws()
                c = self.peek()
                if c == '}':
                    self.advance()
                    return obj
                elif c == ',':
                    self.advance()
                    self.skip_ws()
                    if self.peek() == '}':
                        raise ValueError("Trailing comma in object")
                else:
                    raise ValueError(f"Expected ',' or '}}' in object, got {c}")

    parser = Parser(text)
    return parser.parse()
