import heapq
from collections import defaultdict

def alien_order(words: list[str]) -> str:
    # Collect all unique characters present in the words
    chars = set()
    for w in words:
        for c in w:
            chars.add(c)

    # If no characters, return empty string
    if not chars:
        return ""

    # Graph to store dependencies: char -> set of chars that must come after
    graph = defaultdict(set)
    # In-degree count for each character
    in_degree = {c: 0 for c in chars}

    # Build the graph by comparing adjacent words
    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i+1]
        min_len = min(len(w1), len(w2))

        # Check for invalid prefix case: w1 is longer than w2 and w2 is a prefix of w1
        # e.g., ["abc", "ab"] is invalid because "ab" should come before "abc"
        if len(w1) > len(w2) and w1.startswith(w2):
            return ""

        # Find the first differing character to establish order
        for j in range(min_len):
            if w1[j] != w2[j]:
                u, v = w1[j], w2[j]
                # Add edge u -> v if not already present to avoid double counting in-degree
                if v not in graph[u]:
                    graph[u].add(v)
                    in_degree[v] += 1
                break

    # Initialize priority queue with characters having 0 in-degree
    # Using a min-heap ensures we pick the lexicographically smallest character available
    pq = []
    for c in chars:
        if in_degree[c] == 0:
            heapq.heappush(pq, c)

    result = []
    while pq:
        u = heapq.heappop(pq)
        result.append(u)

        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(pq, v)

    # If the result does not contain all characters, there was a cycle
    if len(result) != len(chars):
        return ""

    return "".join(result)
