def words_to_number(text: str) -> int:
    units = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }
    teens = {
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14,
        'fifteen': 15, 'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19
    }
    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    num_map = {}
    num_map.update(units)
    num_map.update(teens)
    num_map.update(tens)

    # Replace hyphens with spaces to handle compound numbers like 'forty-two'
    text = text.replace('-', ' ')
    words = text.split()

    if not words:
        return 0

    negative = False
    if words[0] == 'minus':
        negative = True
        words = words[1:]

    # Remove 'and' as it does not contribute to the numerical value
    words = [w for w in words if w != 'and']

    if not words:
        return 0

    total = 0
    current = 0

    for word in words:
        if word in num_map:
            current += num_map[word]
        elif word == 'hundred':
            current *= 100
        elif word == 'thousand':
            total += current * 1000
            current = 0
        elif word == 'million':
            total += current * 1000000
            current = 0
        elif word == 'billion':
            total += current * 1000000000
            current = 0

    result = total + current
    if negative:
        result = -result

    return result
