import re

def eval_bool(expr: str, env: dict[str, bool]) -> bool:
    # Tokenize the expression
    # Pattern matches identifiers, parentheses, and skips whitespace
    # We use finditer to detect invalid characters between tokens
    token_pattern = re.compile(r'\s*([a-zA-Z_]\w*|\(|\))')

    tokens = []
    last_pos = 0

    for match in token_pattern.finditer(expr):
        # Check for invalid characters between the previous token and this one
        between = expr[last_pos:match.start()]
        if between.strip():
            raise SyntaxError(f"Invalid character(s) in expression: '{between}'")

        tokens.append(match.group(1))
        last_pos = match.end()

    # Check for invalid characters after the last token
    if expr[last_pos:].strip():
        raise SyntaxError(f"Invalid character(s) in expression: '{expr[last_pos:]}'")

    # Classify tokens
    # Types: 'ID', 'LIT', 'OP', 'LPAREN', 'RPAREN'
    # Values: string for ID/OP/LPAREN/RPAREN, bool for LIT
    classified_tokens = []
    keywords = {'true', 'false', 'not', 'and', 'or'}

    for t in tokens:
        if t == '(':
            classified_tokens.append(('LPAREN', '('))
        elif t == ')':
            classified_tokens.append(('RPAREN', ')'))
        elif t in keywords:
            if t == 'true':
                classified_tokens.append(('LIT', True))
            elif t == 'false':
                classified_tokens.append(('LIT', False))
            else:
                classified_tokens.append(('OP', t))
        else:
            classified_tokens.append(('ID', t))

    # Parser state
    idx = 0
    n = len(classified_tokens)

    def peek():
        if idx < n:
            return classified_tokens[idx]
        return None

    def consume():
        nonlocal idx
        tok = classified_tokens[idx]
        idx += 1
        return tok

    def parse_expr():
        return parse_or()

    def parse_or():
        lhs = parse_and()
        while True:
            tok = peek()
            if tok and tok[0] == 'OP' and tok[1] == 'or':
                consume()
                rhs = parse_and()
                lhs = lhs or rhs
            else:
                break
        return lhs

    def parse_and():
        lhs = parse_not()
        while True:
            tok = peek()
            if tok and tok[0] == 'OP' and tok[1] == 'and':
                consume()
                rhs = parse_not()
                lhs = lhs and rhs
            else:
                break
        return lhs

    def parse_not():
        tok = peek()
        if tok and tok[0] == 'OP' and tok[1] == 'not':
            consume()
            val = parse_not()
            return not val
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok is None:
            raise SyntaxError("Unexpected end of expression")

        if tok[0] == 'LPAREN':
            consume()
            val = parse_expr()
            tok = peek()
            if tok is None or tok[0] != 'RPAREN':
                raise SyntaxError("Expected ')'")
            consume()
            return val
        elif tok[0] == 'LIT':
            consume()
            return tok[1]
        elif tok[0] == 'ID':
            consume()
            var_name = tok[1]
            if var_name not in env:
                raise KeyError(var_name)
            return env[var_name]
        else:
            raise SyntaxError(f"Unexpected token: {tok[1]}")

    result = parse_expr()

    if idx < n:
        raise SyntaxError("Unexpected tokens after expression")

    return result
