def islands_after_adds(rows: int, cols: int, positions: list[tuple[int, int]]) -> list[int]:
    if rows <= 0 or cols <= 0:
        return []

    total_cells = rows * cols
    parent = list(range(total_cells))
    rank = [0] * total_cells
    is_land = [False] * total_cells

    num_islands = 0
    result = []

    def find(i):
        root = i
        while root != parent[root]:
            root = parent[root]
        curr = i
        while curr != root:
            nxt = parent[curr]
            parent[curr] = root
            curr = nxt
        return root

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            if rank[root_i] < rank[root_j]:
                parent[root_i] = root_j
            elif rank[root_i] > rank[root_j]:
                parent[root_j] = root_i
            else:
                parent[root_j] = root_i
                rank[root_i] += 1
            return True
        return False

    for r, c in positions:
        if not (0 <= r < rows and 0 <= c < cols):
            result.append(num_islands)
            continue

        idx = r * cols + c

        if is_land[idx]:
            result.append(num_islands)
            continue

        is_land[idx] = True
        num_islands += 1

        # Check Up
        if r > 0:
            n_idx = idx - cols
            if is_land[n_idx] and union(idx, n_idx):
                num_islands -= 1
        # Check Down
        if r < rows - 1:
            n_idx = idx + cols
            if is_land[n_idx] and union(idx, n_idx):
                num_islands -= 1
        # Check Left
        if c > 0:
            n_idx = idx - 1
            if is_land[n_idx] and union(idx, n_idx):
                num_islands -= 1
        # Check Right
        if c < cols - 1:
            n_idx = idx + 1
            if is_land[n_idx] and union(idx, n_idx):
                num_islands -= 1

        result.append(num_islands)

    return result
