def regex_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)
    # dp[i][j] indicates whether s[:i] matches p[:j]
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(1, n + 1):
        char_p = p[j-1]
        if char_p in ['*', '+', '?']:
            atom = p[j-2]
            for i in range(m + 1):
                if char_p == '*':
                    # Zero occurrences: match s[:i] with p[:j-2]
                    dp[i][j] = dp[i][j-2]
                    # One or more occurrences: if s[i-1] matches atom, 
                    # extend match from s[:i-1] with p[:j]
                    if i > 0 and (s[i-1] == atom or atom == '.'):
                        dp[i][j] = dp[i][j] or dp[i-1][j]
                elif char_p == '+':
                    # One or more occurrences
                    if i > 0 and (s[i-1] == atom or atom == '.'):
                        # Either extend existing match of p[:j] (dp[i-1][j])
                        # or match the first atom after p[:j-2] (dp[i-1][j-2])
                        dp[i][j] = dp[i-1][j] or dp[i-1][j-2]
                    else:
                        dp[i][j] = False
                elif char_p == '?':
                    # Zero occurrences: match s[:i] with p[:j-2]
                    dp[i][j] = dp[i][j-2]
                    # One occurrence: if s[i-1] matches atom, match s[:i-1] with p[:j-2]
                    if i > 0 and (s[i-1] == atom or atom == '.'):
                        dp[i][j] = dp[i][j] or dp[i-1][j-2]
        else:
            for i in range(m + 1):
                if i > 0 and (s[i-1] == char_p or char_p == '.'):
                    dp[i][j] = dp[i-1][j-1]
                else:
                    dp[i][j] = False

    return dp[m][n]
