def justify(words: list[str], width: int) -> list[str]:
    def format_line(line_words, w, is_last):
        if is_last or len(line_words) == 1:
            return " ".join(line_words).ljust(w)

        total_chars = sum(len(x) for x in line_words)
        num_gaps = len(line_words) - 1
        total_spaces = w - total_chars

        base = total_spaces // num_gaps
        extra = total_spaces % num_gaps

        res = []
        for i, word in enumerate(line_words):
            res.append(word)
            if i < num_gaps:
                spaces = base + (1 if i < extra else 0)
                res.append(" " * spaces)
        return "".join(res)

    if not words:
        return []

    lines = []
    current_line = []
    current_len = 0

    for word in words:
        if not current_line:
            next_len = len(word)
        else:
            next_len = current_len + 1 + len(word)

        if next_len <= width:
            current_line.append(word)
            current_len = next_len
        else:
            lines.append(format_line(current_line, width, False))
            current_line = [word]
            current_len = len(word)

    if current_line:
        lines.append(format_line(current_line, width, True))

    return lines
