def parse_json(text: str) -> object:
    class Parser:
        def __init__(self, text):
            self.text = text
            self.pos = 0
            self.length = len(text)

        def peek(self):
            if self.pos < self.length:
                return self.text[self.pos]
            return None

        def advance(self):
            c = self.peek()
            self.pos += 1
            return c

        def skip_whitespace(self):
            while self.pos < self.length and self.text[self.pos] in ' \t\n\r':
                self.pos += 1

        def expect(self, char):
            if self.peek() != char:
                raise ValueError(f"Expected '{char}' at position {self.pos}")
            self.advance()

        def parse(self):
            self.skip_whitespace()
            if self.pos >= self.length:
                raise ValueError("Empty input")
            value = self.parse_value()
            self.skip_whitespace()
            if self.pos < self.length:
                raise ValueError("Trailing characters after JSON value")
            return value

        def parse_value(self):
            c = self.peek()
            if c == '{':
                return self.parse_object()
            elif c == '[':
                return self.parse_array()
            elif c == '"':
                return self.parse_string()
            elif c == 't' or c == 'f':
                return self.parse_literal('true') if c == 't' else self.parse_literal('false')
            elif c == 'n':
                return self.parse_literal('null')
            elif c == '-' or (c and c.isdigit()):
                return self.parse_number()
            else:
                raise ValueError(f"Unexpected character '{c}' at position {self.pos}")

        def parse_object(self):
            self.expect('{')
            d = {}
            self.skip_whitespace()
            if self.peek() == '}':
                self.advance()
                return d

            while True:
                self.skip_whitespace()
                key = self.parse_string()
                self.skip_whitespace()
                self.expect(':')
                self.skip_whitespace()
                value = self.parse_value()
                d[key] = value

                self.skip_whitespace()
                c = self.peek()
                if c == '}':
                    self.advance()
                    return d
                elif c == ',':
                    self.advance()
                    self.skip_whitespace()
                    if self.peek() == '}':
                        raise ValueError("Trailing comma in object")
                else:
                    raise ValueError(f"Expected ',' or '}}' at position {self.pos}")

        def parse_array(self):
            self.expect('[')
            lst = []
            self.skip_whitespace()
            if self.peek() == ']':
                self.advance()
                return lst

            while True:
                self.skip_whitespace()
                value = self.parse_value()
                lst.append(value)

                self.skip_whitespace()
                c = self.peek()
                if c == ']':
                    self.advance()
                    return lst
                elif c == ',':
                    self.advance()
                    self.skip_whitespace()
                    if self.peek() == ']':
                        raise ValueError("Trailing comma in array")
                else:
                    raise ValueError(f"Expected ',' or ']' at position {self.pos}")

        def parse_string(self):
            self.expect('"')
            res = []
            while True:
                c = self.peek()
                if c is None:
                    raise ValueError("Unterminated string")
                if c == '"':
                    self.advance()
                    return "".join(res)
                if c == '\\':
                    self.advance()
                    esc = self.advance()
                    if esc is None:
                        raise ValueError("Unterminated string escape")
                    if esc == '"':
                        res.append('"')
                    elif esc == '\\':
                        res.append('\\')
                    elif esc == '/':
                        res.append('/')
                    elif esc == 'b':
                        res.append('\b')
                    elif esc == 'f':
                        res.append('\f')
                    elif esc == 'n':
                        res.append('\n')
                    elif esc == 'r':
                        res.append('\r')
                    elif esc == 't':
                        res.append('\t')
                    elif esc == 'u':
                        hex_chars = ""
                        for _ in range(4):
                            hc = self.advance()
                            if hc is None or hc not in '0123456789abcdefABCDEF':
                                raise ValueError("Invalid unicode escape")
                            hex_chars += hc
                        try:
                            code_point = int(hex_chars, 16)
                            res.append(chr(code_point))
                        except ValueError:
                            raise ValueError("Invalid unicode escape")
                    else:
                        raise ValueError(f"Invalid escape sequence '\\{esc}'")
                else:
                    if ord(c) < 32:
                         raise ValueError("Unescaped control character in string")
                    res.append(c)
                    self.advance()

        def parse_number(self):
            start = self.pos
            if self.peek() == '-':
                self.advance()

            if self.peek() == '0':
                self.advance()
                if self.pos < self.length and self.text[self.pos].isdigit():
                    raise ValueError("Leading zeros not allowed")
            elif self.peek() and self.text[self.pos].isdigit():
                while self.pos < self.length and self.text[self.pos].isdigit():
                    self.advance()
            else:
                raise ValueError("Invalid number")

            is_float = False
            if self.peek() == '.':
                is_float = True
                self.advance()
                if not (self.pos < self.length and self.text[self.pos].isdigit()):
                    raise ValueError("Invalid number: expected digit after '.'")
                while self.pos < self.length and self.text[self.pos].isdigit():
                    self.advance()

            if self.peek() and self.text[self.pos] in ('e', 'E'):
                is_float = True
                self.advance()
                if self.peek() in ('+', '-'):
                    self.advance()
                if not (self.pos < self.length and self.text[self.pos].isdigit()):
                    raise ValueError("Invalid number: expected digit in exponent")
                while self.pos < self.length and self.text[self.pos].isdigit():
                    self.advance()

            num_str = self.text[start:self.pos]
            if is_float:
                return float(num_str)
            else:
                return int(num_str)

        def parse_literal(self, expected):
            for char in expected:
                if self.peek() != char:
                    raise ValueError(f"Invalid literal '{expected}'")
                self.advance()
            return {'true': True, 'false': False, 'null': None}[expected]

    parser = Parser(text)
    return parser.parse()
