def num_decodings(s: str) -> int:
    MOD = 1_000_000_007

    n = len(s)
    if n == 0:
        return 1

    # dp[i] represents the number of ways to decode s[:i]
    # We use two variables to store dp[i-2] (prev2) and dp[i-1] (prev1)

    # Base case: dp[0] = 1 (empty string has 1 way)
    prev2 = 1 

    # Calculate dp[1] based on s[0]
    c = s[0]
    if c == '0':
        prev1 = 0
    elif c == '*':
        prev1 = 9
    else:
        prev1 = 1

    if n == 1:
        return prev1

    # Iterate from the second character to the end
    for i in range(1, n):
        curr = 0
        c = s[i]
        prev_c = s[i-1]

        # Single digit decoding
        if c == '*':
            curr = (curr + 9 * prev1) % MOD
        elif c != '0':
            curr = (curr + prev1) % MOD

        # Two digit decoding
        if prev_c == '1':
            if c == '*':
                # 11-19
                curr = (curr + 9 * prev2) % MOD
            else:
                # 10-19 (c is a digit)
                curr = (curr + prev2) % MOD
        elif prev_c == '2':
            if c == '*':
                # 21-26
                curr = (curr + 6 * prev2) % MOD
            elif c <= '6':
                # 20-26
                curr = (curr + prev2) % MOD
        elif prev_c == '*':
            if c == '*':
                # 11-19 (9) + 21-26 (6) = 15
                curr = (curr + 15 * prev2) % MOD
            elif c <= '6':
                # 10-16 (1) + 20-26 (1) = 2
                curr = (curr + 2 * prev2) % MOD
            elif c <= '9':
                # 17-19 (1)
                curr = (curr + 1 * prev2) % MOD

        prev2 = prev1
        prev1 = curr

    return prev1
