import heapq
from collections import defaultdict

def alien_order(words: list[str]) -> str:
    # Identify all unique characters present in the words
    unique_chars = set()
    for w in words:
        for c in w:
            unique_chars.add(c)

    # Build the graph: adjacency list and in-degree map
    adj = defaultdict(set)
    in_degree = {c: 0 for c in unique_chars}

    # Compare adjacent words to establish character order
    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i+1]
        min_len = min(len(w1), len(w2))

        # Invalid case: w1 is a longer prefix of w2 (e.g., "abc" before "ab")
        if len(w1) > len(w2) and w1[:min_len] == w2:
            return ""

        # Find the first position where characters differ
        for j in range(min_len):
            if w1[j] != w2[j]:
                u, v = w1[j], w2[j]
                # Add directed edge u -> v if it doesn't exist yet
                if v not in adj[u]:
                    adj[u].add(v)
                    in_degree[v] += 1
                break

    # Initialize min-heap with all characters having 0 in-degree
    # Using a min-heap allows us to greedily select the lexicographically smallest character
    heap = [c for c in unique_chars if in_degree[c] == 0]
    heapq.heapify(heap)

    result = []

    # Perform topological sort
    while heap:
        u = heapq.heappop(heap)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    # If the result length is less than unique characters, a cycle exists
    if len(result) != len(unique_chars):
        return ""

    return "".join(result)
