    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    scales = {
        'thousand': 1000,
        'million': 1000000,
        'billion': 1000000000
    }

    small_numbers = {**units, **tens}

    current_val = 0
    total_val = 0

    for word in words:
        if word in small_numbers:
            current_val += small_numbers[word]
        elif word == 'hundred':
