import re

def eval_bool(expr: str, env: dict[str, bool]) -> bool:
    # Token patterns
    # Keywords must be listed before IDENT to ensure 'true' is recognized as a keyword
    # and not part of an identifier like 'true_var'.
    token_patterns = [
        ('LPAREN', r'\('),
        ('RPAREN', r'\)'),
        ('KEYWORD', r'(?:true|false|not|and|or)\b'),
        ('IDENT', r'[a-zA-Z_][a-zA-Z0-9_]*'),
        ('SKIP', r'\s+'),
    ]

    # Create combined regex
    pattern = '|'.join(f'(?P<{name}>{p})' for name, p in token_patterns)
    tok_regex = re.compile(pattern)

    tokens = []
    pos = 0
    n = len(expr)

    # Tokenize
    while pos < n:
        match = tok_regex.match(expr, pos)
        if not match:
            raise ValueError(f"Invalid character at position {pos}")

        kind = match.lastgroup
        value = match.group()

        if kind == 'SKIP':
            pass
        elif kind == 'KEYWORD':
            if value == 'true':
                tokens.append(('TRUE', True))
            elif value == 'false':
                tokens.append(('FALSE', False))
            elif value == 'not':
                tokens.append(('NOT', None))
            elif value == 'and':
                tokens.append(('AND', None))
            elif value == 'or':
                tokens.append(('OR', None))
        elif kind == 'IDENT':
            tokens.append(('IDENT', value))
        elif kind == 'LPAREN':
            tokens.append(('LPAREN', None))
        elif kind == 'RPAREN':
            tokens.append(('RPAREN', None))

        pos = match.end()

    tokens.append(('EOF', None))
    iterator = iter(tokens)
    current_token = next(iterator)

    def peek():
        return current_token

    def consume(expected_type=None):
        nonlocal current_token
        token = current_token
        try:
            current_token = next(iterator)
        except StopIteration:
            current_token = ('EOF', None)

        if expected_type and token[0] != expected_type:
            raise ValueError(f"Expected {expected_type}, got {token[0]}")
        return token

    # Recursive Descent Parser

    def parse_expr():
        # expr -> term (or term)*
        val = parse_term()
        while peek()[0] == 'OR':
            consume('OR')
            rhs = parse_term()
            val = val or rhs
        return val

    def parse_term():
        # term -> factor (and factor)*
        val = parse_factor()
        while peek()[0] == 'AND':
            consume('AND')
            rhs = parse_factor()
            val = val and rhs
        return val

    def parse_factor():
        # factor -> not factor | primary
        if peek()[0] == 'NOT':
            consume('NOT')
            val = parse_factor()
            return not val
        return parse_primary()

    def parse_primary():
        # primary -> IDENT | TRUE | FALSE | ( expr )
        token = peek()
        kind = token[0]

        if kind == 'IDENT':
            consume('IDENT')
            name = token[1]
            if name not in env:
                raise KeyError(name)
            return env[name]
        elif kind == 'TRUE':
            consume('TRUE')
            return True
        elif kind == 'FALSE':
            consume('FALSE')
            return False
        elif kind == 'LPAREN':
            consume('LPAREN')
            val = parse_expr()
            if peek()[0] != 'RPAREN':
                raise ValueError("Missing closing parenthesis")
            consume('RPAREN')
            return val
        else:
            raise ValueError(f"Unexpected token {kind}")

    result = parse_expr()

    if peek()[0] != 'EOF':
        raise ValueError("Unexpected tokens after expression")

    return result
