def regex_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)
    # dp[i][j] indicates whether s[:i] matches p[:j]
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    def match(c1, c2):
        return c1 == c2 or c2 == '.'

    for j in range(1, n + 1):
        char_p = p[j-1]
        if char_p in '*+?':
            # Quantifier applies to the previous character
            prev_char = p[j-2]
            for i in range(m + 1):
                if char_p == '*':
                    # '*' means zero or more
                    # Case 1: Zero occurrences -> match prefix p[:j-2]
                    dp[i][j] = dp[i][j-2]
                    # Case 2: One or more occurrences -> match s[i-1] with prev_char
                    # and s[:i-1] matches p[:j] (which includes the *)
                    if i > 0 and match(s[i-1], prev_char):
                        dp[i][j] = dp[i][j] or dp[i-1][j]
                elif char_p == '+':
                    # '+' means one or more
                    # Must match at least one character
                    if i > 0 and match(s[i-1], prev_char):
                        # Either continue an existing match of p[:j] (dp[i-1][j])
                        # or start the match of p[:j] from p[:j-2] (dp[i-1][j-2])
                        dp[i][j] = dp[i-1][j] or dp[i-1][j-2]
                elif char_p == '?':
                    # '?' means zero or one
                    # Case 1: Zero occurrences -> match prefix p[:j-2]
                    dp[i][j] = dp[i][j-2]
                    # Case 2: One occurrence -> match s[i-1] with prev_char
                    # and s[:i-1] matches p[:j-2]
                    if i > 0 and match(s[i-1], prev_char):
                        dp[i][j] = dp[i][j] or dp[i-1][j-2]
        else:
            # Normal character or '.'
            for i in range(1, m + 1):
                if match(s[i-1], char_p):
                    dp[i][j] = dp[i-1][j-1]

    return dp[m][n]
