def wildcard_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)

    # dp[i][j] means s[:i] matches p[:j]
    dp = [False] * (n + 1)
    dp[0] = True

    # Handle patterns starting with '*'
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[j] = dp[j - 1]
        else:
            break

    for i in range(1, m + 1):
        new_dp = [False] * (n + 1)
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                new_dp[j] = new_dp[j - 1] or dp[j]
            elif p[j - 1] == '?' or p[j - 1] == s[i - 1]:
                new_dp[j] = dp[j - 1]
        dp = new_dp

    return dp[n]
