from __future__ import annotations
import datetime

def business_days(start: str, end: str, holidays: list[str]) -> int:
    try:
        start_date = datetime.date.fromisoformat(start)
        end_date = datetime.date.fromisoformat(end)
    except ValueError:
        return 0

    reverse = False
    if end_date < start_date:
        start_date, end_date = end_date, start_date
        reverse = True

    if start_date == end_date:
        return 0

    delta_days = (end_date - start_date).days

    # Calculate base business days (Mon-Fri) using math
    full_weeks = delta_days // 7
    remaining_days = delta_days % 7

    count = full_weeks * 5

    start_weekday = start_date.weekday()
    for i in range(remaining_days):
        if (start_weekday + i) % 7 < 5:
            count += 1

    # Filter holidays: remove duplicates and non-weekdays
    valid_holidays = set()
    for h_str in holidays:
        try:
            h_date = datetime.date.fromisoformat(h_str)
            if h_date.weekday() < 5:
                valid_holidays.add(h_date)
        except ValueError:
            continue

    # Subtract holidays falling within the range [start_date, end_date)
    for h_date in valid_holidays:
        if start_date <= h_date < end_date:
            count -= 1

    return -count if reverse else count
