def calc(expr: str) -> float:
    class Parser:
        def __init__(self, expr):
            self.expr = expr
            self.pos = 0

        def skip_spaces(self):
            while self.pos < len(self.expr) and self.expr[self.pos].isspace():
                self.pos += 1

        def peek(self):
            self.skip_spaces()
            if self.pos >= len(self.expr):
                return None
            return self.expr[self.pos]

        def peek_next(self):
            idx = self.pos + 1
            if idx < len(self.expr):
                return self.expr[idx]
            return None

        def advance(self):
            self.pos += 1

        def parse_expr(self):
            left = self.parse_term()
            while True:
                op = self.peek()
                if op == '+':
                    self.advance()
                    right = self.parse_term()
                    left = left + right
                elif op == '-':
                    self.advance()
                    right = self.parse_term()
                    left = left - right
                else:
                    break
            return left

        def parse_term(self):
            left = self.parse_power()
            while True:
                op = self.peek()
                if op == '*':
                    self.advance()
                    right = self.parse_power()
                    left = left * right
                elif op == '/':
                    self.advance()
                    right = self.parse_power()
                    left = left / right
                else:
                    break
            return left

        def parse_factor(self):
            sign = 1
            while True:
                c = self.peek()
                if c == '+':
                    self.advance()
                elif c == '-':
                    sign = -sign
                    self.advance()
                else:
                    break
            return sign * self.parse_power()

        def parse_power(self):
            base = self.parse_atom()
            while True:
                if self.peek() == '*' and self.peek_next() == '*':
                    self.advance()
                    self.advance()
                    exp = self.parse_factor()
                    base = base ** exp
                else:
                    break
            return base

        def parse_atom(self):
            self.skip_spaces()
            c = self.peek()
            if c == '(':
                self.advance()
                val = self.parse_expr()
                self.skip_spaces()
                if self.peek() != ')':
                    raise ValueError("Expected )")
                self.advance()
                return val
            elif c is not None and (c.isdigit() or c == '.'):
                return self.parse_number()
            else:
                raise ValueError(f"Unexpected character: {c}")

        def parse_number(self):
            start = self.pos
            has_dot = False
            has_digit = False
            while self.pos < len(self.expr):
                c = self.expr[self.pos]
                if c.isdigit():
                    has_digit = True
                    self.pos += 1
                elif c == '.':
                    if has_dot:
                        break
                    has_dot = True
                    self.pos += 1
                else:
                    break
            if not has_digit:
                raise ValueError("Invalid number")
            s = self.expr[start:self.pos]
            return float(s)

        def parse(self):
            res = self.parse_expr()
            self.skip_spaces()
            if self.pos < len(self.expr):
                raise ValueError("Unexpected characters at end")
            return res

    parser = Parser(expr)
    return parser.parse()
```

