def num_decodings(s: str) -> int:
    MOD = 1000000007
    n = len(s)

    # p1 stores dp[i-1], p2 stores dp[i-2]
    # Base case: dp[0] = 1 (empty string has 1 way)
    # dp[-1] is conceptually 0
    p1 = 1
    p2 = 0

    for i in range(1, n + 1):
        c = s[i-1]

        # Ways to decode ending at i using single digit s[i-1]
        ways_single = 0
        if c == '*':
            ways_single = 9
        elif c != '0':
            ways_single = 1

        current_ways = (p1 * ways_single) % MOD

        # Ways to decode ending at i using two digits s[i-2]s[i-1]
        if i >= 2:
            prev_c = s[i-2]
            ways_double = 0

            if prev_c == '*':
                if c == '*':
                    # ** -> 11-19 (9), 21-26 (6) => 15
                    ways_double = 15
                else:
                    # *d
                    # d in '0'-'6' -> 1d, 2d (2 ways)
                    # d in '7'-'9' -> 1d (1 way)
                    if c <= '6':
                        ways_double = 2
                    else:
                        ways_double = 1
            else:
                # prev_c is digit
                if c == '*':
                    # d*
                    # d='1' -> 11-19 (9)
                    # d='2' -> 21-26 (6)
                    if prev_c == '1':
                        ways_double = 9
                    elif prev_c == '2':
                        ways_double = 6
                    else:
                        ways_double = 0
                else:
                    # dd
                    val = int(prev_c + c)
                    if 10 <= val <= 26:
                        ways_double = 1
                    else:
                        ways_double = 0

            current_ways = (current_ways + p2 * ways_double) % MOD

        p2 = p1
        p1 = current_ways

    return p1
