import heapq

def alien_order(words: list[str]) -> str:
    # Collect all unique characters present in the words
    chars = set()
    for word in words:
        for char in word:
            chars.add(char)

    if not chars:
        return ""

    # Initialize adjacency list and in-degree count for each character
    adj = {char: set() for char in chars}
    in_degree = {char: 0 for char in chars}

    # Iterate through adjacent words to build the graph
    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i+1]
        min_len = min(len(w1), len(w2))

        # Check for the invalid case where a longer word precedes its prefix
        if len(w1) > len(w2) and w1.startswith(w2):
            return ""

        # Find the first differing character to establish order
        for j in range(min_len):
            if w1[j] != w2[j]:
                u, v = w1[j], w2[j]
                # Add directed edge u -> v if it doesn't exist
                if v not in adj[u]:
                    adj[u].add(v)
                    in_degree[v] += 1
                break

    # Initialize the heap with characters having 0 in-degree
    # Using a min-heap ensures we pick the lexicographically smallest character available
    heap = [char for char in chars if in_degree[char] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    # If the result does not contain all characters, there is a cycle
    if len(result) != len(chars):
        return ""

    return "".join(result)
