def islands_after_adds(rows: int, cols: int, positions: list[tuple[int, int]]) -> list[int]:
    if rows <= 0 or cols <= 0:
        return []

    n = rows * cols
    parent = list(range(n))
    rank = [0] * n
    is_land = [False] * n

    def find(i):
        root = i
        while parent[root] != root:
            root = parent[root]
        curr = i
        while curr != root:
            nxt = parent[curr]
            parent[curr] = root
            curr = nxt
        return root

    res = []
    num_islands = 0

    for r, c in positions:
        idx = r * cols + c

        if is_land[idx]:
            res.append(num_islands)
            continue

        is_land[idx] = True
        num_islands += 1

        root_curr = idx

        # Collect valid neighbor indices
        neighbors = []
        if r > 0: neighbors.append(idx - cols)
        if r < rows - 1: neighbors.append(idx + cols)
        if c > 0: neighbors.append(idx - 1)
        if c < cols - 1: neighbors.append(idx + 1)

        for n_idx in neighbors:
            if is_land[n_idx]:
                root_n = find(n_idx)
                if root_curr != root_n:
                    # Union by rank
                    if rank[root_curr] < rank[root_n]:
                        parent[root_curr] = root_n
                        root_curr = root_n
                    elif rank[root_curr] > rank[root_n]:
                        parent[root_n] = root_curr
                    else:
                        parent[root_n] = root_curr
                        rank[root_curr] += 1
                    num_islands -= 1

        res.append(num_islands)

    return res
