import re

def eval_bool(expr: str, env: dict[str, bool]) -> bool:
    # Tokenize the expression
    # Pattern matches identifiers, parentheses. Keywords are also identifiers syntactically
    # but treated semantically differently in the parser.
    token_regex = re.compile(r'\s*([a-zA-Z_]\w*|\(|\))')

    tokens = []
    pos = 0
    length = len(expr)

    while pos < length:
        match = token_regex.match(expr, pos)
        if not match:
            raise ValueError(f"Invalid character at position {pos}")
        tokens.append(match.group(1))
        pos = match.end()

    if not tokens:
        raise ValueError("Empty expression")

    idx = 0
    n = len(tokens)

    def peek():
        if idx < n:
            return tokens[idx]
        return None

    def consume():
        nonlocal idx
        val = tokens[idx]
        idx += 1
        return val

    def parse_expr():
        # expr -> term ('or' term)*
        lhs = parse_term()
        while peek() == 'or':
            consume()
            rhs = parse_term()
            lhs = lhs or rhs
        return lhs

    def parse_term():
        # term -> factor ('and' factor)*
        lhs = parse_factor()
        while peek() == 'and':
            consume()
            rhs = parse_factor()
            lhs = lhs and rhs
        return lhs

    def parse_factor():
        # factor -> 'not' factor | primary
        if peek() == 'not':
            consume()
            return not parse_factor()
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")

        if tok == '(':
            consume()
            val = parse_expr()
            if peek() != ')':
                raise ValueError("Expected ')'")
            consume()
            return val
        elif tok == 'true':
            consume()
            return True
        elif tok == 'false':
            consume()
            return False
        else:
            # Check for reserved keywords or invalid tokens appearing as values
            if tok in ('not', 'and', 'or', ')'):
                raise ValueError(f"Unexpected token '{tok}'")
            consume()
            if tok not in env:
                raise KeyError(tok)
            return env[tok]

    result = parse_expr()

    if idx < n:
        raise ValueError("Unexpected tokens at end of expression")

    return result
